package main

import "fmt"

func counter(deltas <-chan int) <-chan int {
	result := make(chan int, 1)
	go func() {
		total := 0
		for delta := range deltas {
			total += delta
		}
		result <- total
		close(result)
	}()
	return result
}

func main() {
	deltas := make(chan int)
	result := counter(deltas)
	for _, delta := range []int{2, 3, -1} {
		deltas <- delta
	}
	close(deltas)
	fmt.Println(<-result)
}
```
Only the counter goroutine mutates total. Closing the command stream tells that owner to publish its final result.

```go
package main

import (
	"fmt"
	"sync"
	"sync/atomic"
)

type Stats struct {
	requests atomic.Int64
	mu       sync.Mutex
	lastUser string
	lastPath string
}

func (s *Stats) Record(user, path string) {
	s.requests.Add(1)
	s.mu.Lock()
	s.lastUser, s.lastPath = user, path
	s.mu.Unlock()
}

func (s *Stats) Snapshot() (int64, string, string) {
	count := s.requests.Load()
	s.mu.Lock()
	defer s.mu.Unlock()
	return count, s.lastUser, s.lastPath
}

func main() {
	stats := &Stats{}
	var wg sync.WaitGroup
	for i := range 10 {
		i := i
		wg.Go(func() { stats.Record(fmt.Sprint(i), "/jobs") })
	}
	wg.Wait()
	count, _, path := stats.Snapshot()
	fmt.Println(count, path)
}
```
The count is independent; the user/path pair is one invariant. The example uses each primitive only for the state shape it fits.

```go
package main

import (
	"context"
	"fmt"
	"sync"
)

func worker(ctx context.Context, jobs <-chan int, results chan<- int) {
	for {
		select {
		case <-ctx.Done():
			return
		case job, ok := <-jobs:
			if !ok {
				return
			}
			select {
			case results <- job * job:
			case <-ctx.Done():
				return
			}
		}
	}
}

func main() {
	ctx, cancel := context.WithCancel(context.Background())
	defer cancel()
	jobs := make(chan int, 3)
	results := make(chan int)
	for _, job := range []int{2, 3, 4} {
		jobs <- job
	}
	close(jobs)

	var wg sync.WaitGroup
	for range 2 {
		wg.Go(func() { worker(ctx, jobs, results) })
	}
	go func() {
		wg.Wait()
		close(results)
	}()

	total := 0
	for result := range results {
		total += result
	}
	fmt.Println(total)
}
```
Jobs and results carry data, Context provides cancellation, and WaitGroup makes closing the multi-sender results channel safe.
